package com.ptms.service; import com.ptms.domain.*; import com.ptms.dto.*; import com.ptms.exception.*; import com.ptms.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class TicketInventoryService{private final ParkingTicketRepository r;public TicketInventoryService(ParkingTicketRepository r){this.r=r;}public List<TicketDto>all(){return r.findAll().stream().map(this::dto).toList();}public List<TicketDto>remaining(){return r.findByStatusOrderByDurationHoursAscBarcodeAsc(TicketStatus.AVAILABLE).stream().map(this::dto).toList();}public List<TicketDto>bulk(BulkTicketScanRequest q){Set<String>s=new HashSet<>();List<TicketDto>out=new ArrayList<>();for(String raw:q.barcodes()){String b=raw.trim();if(!s.add(b.toLowerCase())||r.findByBarcodeIgnoreCase(b).isPresent())throw new BusinessRuleException("Duplicate barcode: "+b);ParkingTicket t=new ParkingTicket();t.setBarcode(b);t.setDurationHours(q.durationHours());t.setExpiryDate(q.expiryDate());out.add(dto(r.save(t)));}return out;}private TicketDto dto(ParkingTicket t){return new TicketDto(t.getId(),t.getBarcode(),t.getDurationHours(),t.getStatus(),t.getExpiryDate(),t.getIssuedAt(),t.getIssuedToReference());}}
